 36	            reservationRepository,
 37	            roomRepository,
 38	            pricingService,
 39	            notificationService
 40	        );
 41	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 42	
 43	        Gson gson = new Gson();
