 58	
 59	        System.out.println("Pousada Maré Alta API listening on port " + port);
 60	    }
 61	}
 62	package com.pousadamarealta.api;
 63	
 64	import com.google.gson.Gson;
 65	import com.google.gson.JsonObject;
 66	import com.pousadamarealta.exceptions.ApiException;
 67	import com.pousadamarealta.models.*;
 68	import com.pousadamarealta.repositories.MessageRepository;
 69	import com.pousadamarealta.repositories.ReservationRepository;
 70	import com.pousadamarealta.repositories.RoomRepository;
 71	import com.pousadamarealta.services.*;
 72	import io.javalin.Javalin;
 73	import io.javalin.http.Context;
 74	
 75	import java.math.BigDecimal;
 76	import java.time.LocalDate;
 77	import java.time.YearMonth;
 78	import java.time.format.DateTimeFormatter;
 79	import java.util.stream.Collectors;
 80	
 81	public class ApiRoutes {
 82	    private final RoomRepository roomRepository;
 83	    private final ReservationRepository reservationRepository;
 84	    private final MessageRepository messageRepository;
 85	    private final ReservationService reservationService;
 86	    private final NotificationService notificationService;
 87	    private final ReportService reportService;
 88	    private final Gson gson;
 89	
 90	    public ApiRoutes(
 91	        RoomRepository roomRepository,
 92	        ReservationRepository reservationRepository,
 93	        MessageRepository messageRepository,
 94	        ReservationService reservationService,
 95	        NotificationService notificationService,
 96	        ReportService reportService,
 97	        Gson gson
 98	    ) {
 99	        this.roomRepository = roomRepository;
100	        this.reservationRepository = reservationRepository;
101	        this.messageRepository = messageRepository;
102	        this.reservationService = reservationService;
103	        this.notificationService = notificationService;
104	        this.reportService = reportService;
105	        this.gson = gson;
106	    }
107	
108	    public void registerRoutes(Javalin app) {
109	        app.get("/rooms", this::getRooms);
110	        app.post("/reservations", this::createReservation);
111	        app.get("/reservations/{id}", this::getReservation);
112	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
113	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
114	        app.post("/reservations/{id}/check-in", this::checkIn);
115	        app.post("/reservations/{id}/check-out", this::checkOut);
116	        app.get("/reservations/{id}/document", this::getDocument);
117	        app.get("/messages", this::getMessages);
118	        app.get("/reports/occupancy", this::getOccupancyReport);
119	        app.get("/reports/revenue", this::getRevenueReport);
120	    }
121	
122	    private void getRooms(Context ctx) {
123	        try {
124	            var rooms = roomRepository.findAll().stream()
125	                .map(room -> {
126	                    JsonObject json = new JsonObject();
127	                    json.addProperty("number", room.number());
128	                    json.addProperty("type", room.type().toString());
129	                    json.addProperty("capacity", room.capacity());
130	                    json.addProperty("nightlyRate", room.nightlyRate().doubleValue());
131	                    return json;
132	                })
133	                .collect(Collectors.toList());
134	            ctx.json(rooms);
135	        } catch (Exception e) {
136	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao buscar quartos", 400);
137	        }
138	    }
139	
140	    private void createReservation(Context ctx) {
141	        try {
142	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
143	            if (body == null) {
144	                errorResponse(ctx, "INVALID_REQUEST", "Corpo da requisição inválido", 400);
145	                return;
146	            }
147	
148	            validateRequiredFields(body, "roomNumber", "guestName", "guestEmail", "guestCpf",
149	                "checkIn", "checkOut", "guests", "ratePlan");
150	
151	            int roomNumber = body.get("roomNumber").getAsInt();
152	            String guestName = body.get("guestName").getAsString();
153	            String guestEmail = body.get("guestEmail").getAsString();
154	            String guestCpf = body.get("guestCpf").getAsString();
155	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString());
156	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString());
157	            int guests = body.get("guests").getAsInt();
158	            RatePlan ratePlan = RatePlan.valueOf(body.get("ratePlan").getAsString());
159	
160	            Reservation reservation = reservationService.createReservation(
161	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan
162	            );
163	
164	            ctx.status(201);
165	            ctx.json(reservationToJson(reservation));
166	        } catch (ApiException e) {
167	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
168	        } catch (Exception e) {
169	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao criar reserva: " + e.getMessage(), 400);
170	        }
171	    }
172	
173	    private void getReservation(Context ctx) {
174	        try {
175	            int id = ctx.pathParamAsClass("id", Integer.class).get();
176	            Reservation reservation = reservationService.getReservation(id);
177	            ctx.json(reservationToJson(reservation));
178	        } catch (ApiException e) {
179	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
180	        } catch (Exception e) {
181	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao buscar reserva", 400);
182	        }
183	    }
184	
185	    private void confirmReservation(Context ctx) {
186	        try {
187	            int id = ctx.pathParamAsClass("id", Integer.class).get();
188	            Reservation reservation = reservationService.getReservation(id);
189	
190	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
191	            if (body == null || !body.has("amountPaid")) {
192	                errorResponse(ctx, "INVALID_REQUEST", "Campo amountPaid não fornecido", 400);
193	                return;
194	            }
195	
196	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
197	            Reservation confirmed = reservationService.confirmReservation(id, amountPaid);
198	            ctx.json(reservationToJson(confirmed));
199	        } catch (ApiException e) {
200	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
201	        } catch (Exception e) {
202	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao confirmar reserva", 400);
203	        }
204	    }
205	
206	    private void cancelReservation(Context ctx) {
207	        try {
208	            int id = ctx.pathParamAsClass("id", Integer.class).get();
209	            Reservation cancelled = reservationService.cancelReservation(id);
210	            ctx.json(reservationToJson(cancelled));
211	        } catch (ApiException e) {
212	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
213	        } catch (Exception e) {
214	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao cancelar reserva", 400);
215	        }
216	    }
217	
218	    private void checkIn(Context ctx) {
219	        try {
220	            int id = ctx.pathParamAsClass("id", Integer.class).get();
221	            Reservation checked = reservationService.checkIn(id);
222	            ctx.json(reservationToJson(checked));
223	        } catch (ApiException e) {
224	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
225	        } catch (Exception e) {
226	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao fazer check-in", 400);
227	        }
228	    }
229	
230	    private void checkOut(Context ctx) {
231	        try {
232	            int id = ctx.pathParamAsClass("id", Integer.class).get();
233	            Reservation checked = reservationService.checkOut(id);
234	
235	            JsonObject receipt = new JsonObject();
236	            receipt.addProperty("title", "Comprovante de reserva");
237	            receipt.addProperty("reservationId", checked.getId());
238	            receipt.addProperty("guestName", checked.getGuestName());
239	            receipt.addProperty("guestCpf", checked.getGuestCpf());
240	            receipt.addProperty("roomNumber", checked.getRoomNumber());
241	            receipt.addProperty("roomType", getRoomType(checked.getRoomNumber()));
242	            receipt.addProperty("checkIn", checked.getCheckIn().toString());
243	            receipt.addProperty("checkOut", checked.getCheckOut().toString());
244	            receipt.addProperty("nights", checked.getNights());
245	            receipt.addProperty("subtotal", checked.getSubtotal().doubleValue());
246	            receipt.addProperty("discount", checked.getDiscount().doubleValue());
247	            receipt.addProperty("total", checked.getTotal().doubleValue());
248	
249	            ctx.json(receipt);
250	        } catch (ApiException e) {
251	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
252	        } catch (Exception e) {
253	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao fazer check-out", 400);
254	        }
255	    }
256	
257	    private void getDocument(Context ctx) {
258	        try {
259	            int id = ctx.pathParamAsClass("id", Integer.class).get();
260	            Reservation reservation = reservationService.getReservation(id);
261	
262	            if (reservation.getStatus() == ReservationStatus.PENDING) {
263	                errorResponse(ctx, "OPERATION_NOT_ALLOWED",
264	                    "Comprovante não disponível para reserva pendente", 409);
265	                return;
266	            }
267	
268	            JsonObject receipt = new JsonObject();
269	            receipt.addProperty("title", "Comprovante de reserva");
270	            receipt.addProperty("reservationId", reservation.getId());
271	            receipt.addProperty("guestName", reservation.getGuestName());
272	            receipt.addProperty("guestCpf", reservation.getGuestCpf());
273	            receipt.addProperty("roomNumber", reservation.getRoomNumber());
274	            receipt.addProperty("roomType", getRoomType(reservation.getRoomNumber()));
275	            receipt.addProperty("checkIn", reservation.getCheckIn().toString());
276	            receipt.addProperty("checkOut", reservation.getCheckOut().toString());
277	            receipt.addProperty("nights", reservation.getNights());
278	            receipt.addProperty("subtotal", reservation.getSubtotal().doubleValue());
279	            receipt.addProperty("discount", reservation.getDiscount().doubleValue());
280	            receipt.addProperty("total", reservation.getTotal().doubleValue());
281	
282	            ctx.json(receipt);
283	        } catch (ApiException e) {
284	            errorResponse(ctx, e.getErrorCode(), e.getMessage(), e.getStatusCode());
285	        } catch (Exception e) {
286	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao buscar comprovante", 400);
287	        }
288	    }
289	
290	    private void getMessages(Context ctx) {
291	        try {
292	            var messages = messageRepository.findAll().stream()
293	                .map(msg -> {
294	                    JsonObject json = new JsonObject();
295	                    json.addProperty("id", msg.id());
296	                    json.addProperty("channel", msg.channel());
297	                    json.addProperty("to", msg.to());
298	                    json.addProperty("subject", msg.subject());
299	                    json.addProperty("body", msg.body());
300	                    return json;
301	                })
302	                .collect(Collectors.toList());
303	            ctx.json(messages);
304	        } catch (Exception e) {
305	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao buscar mensagens", 400);
306	        }
307	    }
308	
309	    private void getOccupancyReport(Context ctx) {
310	        try {
311	            String dateStr = ctx.queryParam("date");
312	            if (dateStr == null || dateStr.isEmpty()) {
313	                errorResponse(ctx, "INVALID_REQUEST", "Parâmetro 'date' obrigatório", 400);
314	                return;
315	            }
316	
317	            LocalDate date = LocalDate.parse(dateStr);
318	            String report = reportService.generateOccupancyReport(date);
319	            ctx.contentType("text/csv;charset=utf-8");
320	            ctx.result(report);
321	        } catch (Exception e) {
322	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao gerar relatório de ocupação", 400);
323	        }
324	    }
325	
326	    private void getRevenueReport(Context ctx) {
327	        try {
328	            String monthStr = ctx.queryParam("month");
329	            if (monthStr == null || monthStr.isEmpty()) {
330	                errorResponse(ctx, "INVALID_REQUEST", "Parâmetro 'month' obrigatório", 400);
331	                return;
332	            }
333	
334	            YearMonth yearMonth = YearMonth.parse(monthStr);
335	            String report = reportService.generateRevenueReport(yearMonth);
336	            ctx.contentType("text/csv;charset=utf-8");
337	            ctx.result(report);
338	        } catch (Exception e) {
339	            errorResponse(ctx, "INVALID_REQUEST", "Erro ao gerar relatório financeiro", 400);
340	        }
341	    }
342	
343	    private JsonObject reservationToJson(Reservation res) {
344	        JsonObject json = new JsonObject();
345	        json.addProperty("id", res.getId());
346	        json.addProperty("roomNumber", res.getRoomNumber());
347	        json.addProperty("guestName", res.getGuestName());
348	        json.addProperty("guestEmail", res.getGuestEmail());
349	        json.addProperty("guestCpf", res.getGuestCpf());
350	        json.addProperty("checkIn", res.getCheckIn().toString());
351	        json.addProperty("checkOut", res.getCheckOut().toString());
352	        json.addProperty("guests", res.getGuests());
353	        json.addProperty("ratePlan", res.getRatePlan().toString());
354	        json.addProperty("nights", res.getNights());
355	        json.addProperty("subtotal", res.getSubtotal().doubleValue());
356	        json.addProperty("discount", res.getDiscount().doubleValue());
357	        json.addProperty("total", res.getTotal().doubleValue());
358	        json.addProperty("status", res.getStatus().toString());
359	        json.addProperty("amountPaid", res.getAmountPaid().doubleValue());
360	        if (res.getRefund() != null) {
361	            json.addProperty("refund", res.getRefund().doubleValue());
362	        } else {
363	            json.add("refund", null);
364	        }
365	        return json;
366	    }
367	
368	    private String getRoomType(int roomNumber) {
369	        if (roomNumber < 200) return "STANDARD";
370	        if (roomNumber < 300) return "DELUXE";
371	        return "SUITE";
372	    }
373	
374	    private void validateRequiredFields(JsonObject body, String... fields) throws ApiException {
375	        for (String field : fields) {
376	            if (!body.has(field) || body.get(field).isJsonNull()) {
377	                throw new ApiException("INVALID_REQUEST", "Campo obrigatório: " + field, 400);
378	            }
379	        }
380	    }
381	
382	    private void errorResponse(Context ctx, String errorCode, String message, int statusCode) {
383	        ctx.status(statusCode);
384	        JsonObject error = new JsonObject();
385	        error.addProperty("error", errorCode);
386	        error.addProperty("message", message);
387	        ctx.json(error);
388	    }
389	}

