374	    private void validateRequiredFields(JsonObject body, String... fields) throws ApiException {
375	        for (String field : fields) {
376	            if (!body.has(field) || body.get(field).isJsonNull()) {
377	                throw new ApiException("INVALID_REQUEST", "Campo obrigatório: " + field, 400);
378	            }
379	        }
380	    }
381	
382	    private void errorResponse(Context ctx, String errorCode, String message, int statusCode) {
383	        ctx.status(statusCode);
384	        JsonObject error = new JsonObject();
385	        error.addProperty("error", errorCode);
386	        error.addProperty("message", message);
387	        ctx.json(error);
388	    }
389	}

