  7	
  8	public class NotificationService {
  9	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 10	    private static final DateTimeFormatter CURRENCY_FORMAT = DateTimeFormatter.ofPattern("R$ #,##0.00");
 11	    private final MessageRepository messageRepository;
 12	
 13	    public NotificationService(MessageRepository messageRepository) {
 14	        this.messageRepository = messageRepository;
 15	    }
 16	
 17	    public void notifyReservationConfirmed(Reservation reservation) throws Exception {
 18	        notifyGuest(reservation);
 19	        notifyGovernance(reservation, "confirmed");
 20	        notifyFinance(reservation, "payment_received");
 21	    }
 22	
 23	    public void notifyReservationCancelled(Reservation reservation) throws Exception {
 24	        if (reservation.getAmountPaid().compareTo(BigDecimal.ZERO) > 0) {
 25	            notifyGovernance(reservation, "cancelled");
 26	            if (reservation.getRefund() != null && reservation.getRefund().compareTo(BigDecimal.ZERO) > 0) {
 27	                notifyFinance(reservation, "refund");
 28	            }
 29	        }
 30	    }
 31	
 32	    private void notifyGuest(Reservation reservation) throws Exception {
 33	        String receipt = generateReceipt(reservation);
 34	        String subject = "Reserva confirmada - Pousada Maré Alta";
 35	        String body = String.format(
 36	            "Olá, %s!\n\n" +
 37	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
 38	            "%s\n\n" +
 39	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
 40	            "Até breve!",
 41	            reservation.getGuestName(),
 42	            receipt
 43	        );
 44	        messageRepository.save("EMAIL", reservation.getGuestEmail(), subject, body);
 45	    }
 46	
 47	    private void notifyGovernance(Reservation reservation, String type) throws Exception {
 48	        String subject;
 49	        String body;
 50	
 51	        if ("confirmed".equals(type)) {
 52	            subject = "Reserva confirmada - quarto " + reservation.getRoomNumber();
 53	            body = String.format(
 54	                "Quarto: %d\nEntrada: %s\nSaída: %s\nHóspedes: %d",
 55	                reservation.getRoomNumber(),
 56	                reservation.getCheckIn().format(DATE_FORMAT),
 57	                reservation.getCheckOut().format(DATE_FORMAT),
 58	                reservation.getGuests()
 59	            );
 60	        } else if ("cancelled".equals(type)) {
 61	            subject = "Reserva cancelada - quarto " + reservation.getRoomNumber();
 62	            body = String.format(
 63	                "Quarto: %d\nEntrada: %s\nSaída: %s",
 64	                reservation.getRoomNumber(),
 65	                reservation.getCheckIn().format(DATE_FORMAT),
 66	                reservation.getCheckOut().format(DATE_FORMAT)
 67	            );
 68	        } else {
 69	            return;
 70	        }
 71	
 72	        messageRepository.save("EMAIL", "governanca@pousadamarealta.com.br", subject, body);
 73	    }
 74	
 75	    private void notifyFinance(Reservation reservation, String type) throws Exception {
 76	        String subject;
 77	        String body;
 78	
 79	        if ("payment_received".equals(type)) {
 80	            subject = "Pagamento recebido - reserva " + reservation.getId();
 81	            body = String.format(
 82	                "Valor: %s",
 83	                formatCurrency(reservation.getAmountPaid())
 84	            );
 85	        } else if ("refund".equals(type)) {
 86	            subject = "Reembolso - reserva " + reservation.getId();
 87	            body = String.format(
 88	                "Valor: %s",
 89	                formatCurrency(reservation.getRefund())
 90	            );
 91	        } else {
 92	            return;
 93	        }
 94	
 95	        messageRepository.save("EMAIL", "financeiro@pousadamarealta.com.br", subject, body);
 96	    }
 97	
 98	    public String generateReceipt(Reservation reservation) {
 99	        StringBuilder sb = new StringBuilder();
100	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
101	        sb.append(String.format("Hóspede: %s (CPF %s)\n",
102	            reservation.getGuestName(),
103	            formatCpf(reservation.getGuestCpf())));
104	        sb.append(String.format("Quarto: %d (%s)\n",
105	            reservation.getRoomNumber(),
106	            reservation.getRoomNumber() < 200 ? "STANDARD" :
107	            reservation.getRoomNumber() < 300 ? "DELUXE" : "SUITE"));
108	        sb.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
109	            reservation.getCheckIn().format(DATE_FORMAT),
110	            reservation.getCheckOut().format(DATE_FORMAT),
111	            reservation.getNights(),
112	            reservation.getNights() == 1 ? "diária" : "diárias"));
113	        sb.append(String.format("Diárias: %s\n", formatCurrency(reservation.getSubtotal())));
114	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
115	            sb.append(String.format("Desconto: %s\n", formatCurrency(reservation.getDiscount())));
116	        }
117	        sb.append(String.format("Total: %s", formatCurrency(reservation.getTotal())));
118	        return sb.toString();
119	    }
120	
121	    private String formatCurrency(BigDecimal amount) {
122	        String formatted = String.format("%.2f", amount);
123	        String[] parts = formatted.split("\\.");
124	        String intPart = parts[0];
125	        String decPart = parts[1];
126	
127	        StringBuilder result = new StringBuilder("R$ ");
128	        int len = intPart.length();
129	        for (int i = 0; i < len; i++) {
130	            if (i > 0 && (len - i) % 3 == 0) {
131	                result.append(".");
132	            }
133	            result.append(intPart.charAt(i));
134	        }
135	        result.append(",").append(decPart);
136	        return result.toString();
137	    }
138	
139	    private String formatCpf(String cpf) {
140	        if (cpf.length() == 11) {
141	            return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
142	        }
143	        return cpf;
144	    }
145	}
146	package com.pousadamarealta.services;
147	
148	import com.pousadamarealta.models.RatePlan;
149	
150	import java.math.BigDecimal;
151	import java.math.RoundingMode;
152	import java.time.LocalDate;
153	import java.time.Month;
154	
155	public class PricingService {
156	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
157	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = BigDecimal.valueOf(0.15);
158	
159	    public boolean isHighSeason(LocalDate date) {
160	        Month month = date.getMonth();
161	        return (month == Month.DECEMBER || month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY);
162	    }
163	
164	    public BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
165	        if (isHighSeason(date)) {
166	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
167	        }
168	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
169	    }
170	
171	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
172	        BigDecimal subtotal = BigDecimal.ZERO;
173	        LocalDate current = checkIn;
174	        while (current.isBefore(checkOut)) {
175	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
176	            current = current.plusDays(1);
177	        }
178	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
179	    }
180	
181	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
182	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
183	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
184	        }
185	        return BigDecimal.ZERO;
186	    }
187	
188	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
189	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
190	    }
191	
192	    public int countNights(LocalDate checkIn, LocalDate checkOut) {
193	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
194	    }
195	}
