283	package com.pousadamarealta.services;
284	
285	import com.pousadamarealta.exceptions.ApiException;
286	import com.pousadamarealta.models.*;
287	import com.pousadamarealta.repositories.*;
288	
289	import java.math.BigDecimal;
290	import java.time.LocalDate;
291	import java.util.List;
292	import java.util.Optional;
293	
294	public class ReservationService {
295	    private final ReservationRepository reservationRepository;
296	    private final RoomRepository roomRepository;
297	    private final PricingService pricingService;
298	    private final NotificationService notificationService;
299	
300	    public ReservationService(
301	        ReservationRepository reservationRepository,
302	        RoomRepository roomRepository,
303	        PricingService pricingService,
304	        NotificationService notificationService
305	    ) {
306	        this.reservationRepository = reservationRepository;
307	        this.roomRepository = roomRepository;
308	        this.pricingService = pricingService;
309	        this.notificationService = notificationService;
310	    }
311	
312	    public Reservation createReservation(
313	        int roomNumber,
314	        String guestName,
315	        String guestEmail,
316	        String guestCpf,
317	        LocalDate checkIn,
318	        LocalDate checkOut,
319	        int guests,
320	        RatePlan ratePlan
321	    ) throws Exception {
322	        validateReservationInput(roomNumber, checkIn, checkOut, guests);
323	
324	        Optional<Room> roomOpt = roomRepository.findByNumber(roomNumber);
325	        if (roomOpt.isEmpty()) {
326	            throw new ApiException("ROOM_NOT_FOUND", "Quarto não encontrado", 404);
327	        }
328	
329	        Room room = roomOpt.get();
330	        if (guests > room.capacity()) {
331	            throw new ApiException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto", 422);
332	        }
333	
334	        checkRoomAvailability(roomNumber, checkIn, checkOut);
335	
336	        int nights = pricingService.countNights(checkIn, checkOut);
337	        BigDecimal subtotal = pricingService.calculateSubtotal(room.nightlyRate(), checkIn, checkOut);
338	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
339	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
340	
341	        Reservation reservation = new Reservation(
342	            0,
343	            roomNumber,
344	            guestName,
345	            guestEmail,
346	            guestCpf,
347	            checkIn,
348	            checkOut,
349	            guests,
350	            ratePlan,
351	            nights,
352	            subtotal,
353	            discount,
354	            total
355	        );
356	
357	        return reservationRepository.save(reservation);
358	    }
359	
360	    public Reservation getReservation(int id) throws Exception {
361	        Optional<Reservation> resOpt = reservationRepository.findById(id);
362	        if (resOpt.isEmpty()) {
363	            throw new ApiException("RESERVATION_NOT_FOUND", "Reserva não encontrada", 404);
364	        }
365	        return resOpt.get();
366	    }
367	
368	    public Reservation confirmReservation(int id, BigDecimal amountPaid) throws Exception {
369	        Reservation reservation = getReservation(id);
370	
371	        if (reservation.getStatus() != ReservationStatus.PENDING) {
372	            throw new ApiException("OPERATION_NOT_ALLOWED",
373	                "Apenas reservas pendentes podem ser confirmadas", 409);
374	        }
375	
376	        reservation.setStatus(ReservationStatus.CONFIRMED);
377	        reservation.setAmountPaid(amountPaid);
378	        reservationRepository.update(reservation);
379	
380	        notificationService.notifyReservationConfirmed(reservation);
381	
382	        return reservation;
383	    }
384	
385	    public Reservation checkIn(int id) throws Exception {
386	        Reservation reservation = getReservation(id);
387	
388	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
389	            throw new ApiException("OPERATION_NOT_ALLOWED",
390	                "Apenas reservas confirmadas podem fazer check-in", 409);
391	        }
