148	import com.pousadamarealta.models.RatePlan;
149	
150	import java.math.BigDecimal;
151	import java.math.RoundingMode;
152	import java.time.LocalDate;
153	import java.time.Month;
154	
155	public class PricingService {
156	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
157	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = BigDecimal.valueOf(0.15);
158	
159	    public boolean isHighSeason(LocalDate date) {
160	        Month month = date.getMonth();
161	        return (month == Month.DECEMBER || month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY);
162	    }
163	
164	    public BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
165	        if (isHighSeason(date)) {
166	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
167	        }
168	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
169	    }
170	
171	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
172	        BigDecimal subtotal = BigDecimal.ZERO;
173	        LocalDate current = checkIn;
174	        while (current.isBefore(checkOut)) {
175	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
176	            current = current.plusDays(1);
177	        }
178	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
179	    }
180	
181	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
182	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
183	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
184	        }
185	        return BigDecimal.ZERO;
186	    }
187	
188	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
189	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
190	    }
191	
192	    public int countNights(LocalDate checkIn, LocalDate checkOut) {
193	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
194	    }
195	}
