 17	        try (Connection conn = dbConfig.getConnection()) {
 18	            try (PreparedStatement stmt = conn.prepareStatement(
 19	                "INSERT INTO messages (channel, \"to\", subject, body) VALUES (?, ?, ?, ?)"
