292	    public List<Room> findAll() throws SQLException {
293	        List<Room> rooms = new ArrayList<>();
294	        try (Connection conn = dbConfig.getConnection()) {
295	            try (Statement stmt = conn.createStatement()) {
296	                try (ResultSet rs = stmt.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
297	                    while (rs.next()) {
298	                        rooms.add(new Room(
