311	    public Optional<Room> findByNumber(int number) throws SQLException {
312	        try (Connection conn = dbConfig.getConnection()) {
313	            try (PreparedStatement stmt = conn.prepareStatement("SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
314	                stmt.setInt(1, number);
315	                try (ResultSet rs = stmt.executeQuery()) {
316	                    if (rs.next()) {
317	                        return Optional.of(new Room(
318	                            rs.getInt("number"),
319	                            RoomType.valueOf(rs.getString("type")),
320	                            rs.getInt("capacity"),
321	                            rs.getBigDecimal("nightly_rate")
